const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8080';

class ApiClient {
  async request(endpoint, options = {}) {
    const url = `${API_BASE_URL}${endpoint}`;
    const config = {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    };

    const response = await fetch(url, config);

    if (!response.ok) {
      throw new Error(`API request failed: ${response.statusText}`);
    }

    return response.json();
  }

  get(endpoint) {
    return this.request(endpoint, { method: 'GET' });
  }

  post(endpoint, data) {
    return this.request(endpoint, {
      method: 'POST',
      body: JSON.stringify(data),
    });
  }
}

export default new ApiClient();

package main

import (
    "net/http"
    "github.com/gin-gonic/gin"
)

type Task struct {
    ID          uint   `json:"id"`
    Title       string `json:"title"`
    Description string `json:"description"`
    Status      string `json:"status"`
}

func main() {
    router := gin.Default()

    router.Use(gin.Logger())
    router.Use(gin.Recovery())

    api := router.Group("/api")
    {
        api.GET("/tasks", getTasks)
        api.GET("/tasks/:id", getTask)
        api.POST("/tasks", createTask)
        api.PUT("/tasks/:id", updateTask)
        api.DELETE("/tasks/:id", deleteTask)
    }

    router.Run(":8080")
}

func getTasks(c *gin.Context) {
    tasks := []Task{
        {ID: 1, Title: "Sample Task", Description: "Description", Status: "pending"},
    }
    c.JSON(http.StatusOK, tasks)
}

func createTask(c *gin.Context) {
    var task Task
    if err := c.ShouldBindJSON(&task); err != nil {
        c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
        return
    }
    c.JSON(http.StatusCreated, task)
}

package models

import (
    "time"
    "gorm.io/gorm"
    "gorm.io/driver/postgres"
)

type Task struct {
    ID          uint           `gorm:"primaryKey"`
    Title       string         `gorm:"size:255;not null"`
    Description string         `gorm:"type:text"`
    Status      string         `gorm:"size:50;default:'pending'"`
    CreatedAt   time.Time
    UpdatedAt   time.Time
    DeletedAt   gorm.DeletedAt `gorm:"index"`
}

type TaskRepository struct {
    db *gorm.DB
}

func NewTaskRepository(db *gorm.DB) *TaskRepository {
    return &TaskRepository{db: db}
}

func (r *TaskRepository) Create(task *Task) error {
    return r.db.Create(task).Error
}

func (r *TaskRepository) GetByID(id uint) (*Task, error) {
    var task Task
    err := r.db.First(&task, id).Error
    return &task, err
}

func InitDB() (*gorm.DB, error) {
    dsn := "host=localhost user=myuser password=mypass dbname=mydb port=5432"
    return gorm.Open(postgres.Open(dsn), &gorm.Config{})
}

const express = require('express');
const cors = require('cors');
const app = express();
const PORT = process.env.PORT || 3000;

app.use(cors());
app.use(express.json());

app.get('/api/tasks', async (req, res) => {
  try {
    const tasks = [
      { id: 1, title: 'Task 1', status: 'pending' },
      { id: 2, title: 'Task 2', status: 'completed' }
    ];
    res.json(tasks);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

app.post('/api/tasks', async (req, res) => {
  try {
    const { title, description } = req.body;
    const newTask = { id: Date.now(), title, description, status: 'pending' };
    res.status(201).json(newTask);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

